// Merged schema.
// Ref: #/components/schemas/BusinessPartner
type BusinessPartner struct {
	// Identifier (UUIDv7).
	ID uuid.UUID `json:"id"`
	// Optimistic-lock version; equals the ETag. Increases by one on every change.
	Version int32 `json:"version"`
	// Creation time (UTC).
	CreatedAt time.Time `json:"created_at"`
	// Principal that created the resource.
	CreatedBy uuid.UUID `json:"created_by"`
	// Time of the last change (UTC).
	UpdatedAt time.Time `json:"updated_at"`
	// Principal that made the last change. Absent on resources whose table does not record it.
	UpdatedBy OptUUID `json:"updated_by"`
	// Business partner number.
	Number string `json:"number"`
	// Kind of partner. Open enumeration: clients must accept and preserve values not listed here; values
	// may be added within /v1.
	Kind string `json:"kind"`
	// Name.
	Name string `json:"name"`
	// Legal name, if different.
	LegalName OptString `json:"legal_name"`
	// Country.
	CountryCode string `json:"country_code"`
	// Correspondence language (ISO 639-1).
	Language OptString `json:"language"`
	// Lifecycle status. Open enumeration: clients must accept and preserve values not listed here; values
	// may be added within /v1.
	Status string `json:"status"`
	// Roles the partner plays.
	Roles []string `json:"roles"`
	// Supplier data per legal entity.
	SupplierCompanies []SupplierCompany `json:"supplier_companies"`
	// Customer data per legal entity (role `customer`), of the legal entities the caller may act in,
	// ordered by legal entity id (T74a). Empty for a partner that is no customer, or is one without
	// company data.
	CustomerCompanies []CustomerCompany `json:"customer_companies"`
	// Addresses.
	Addresses []Address `json:"addresses"`
	// Tax identifiers, masked.
	TaxIdentifiers []TaxIdentifier `json:"tax_identifiers"`
	// Custom fields.
	Extensions Extensions `json:"extensions"`
	// The legal entity of the tenant this partner is, when it is one of the group's companies (ADR-0059
	// §4): the trading partner the ledger gives the lines that name the partner from then on. Absent:
	// none.
	GroupCompanyID OptUUID `json:"group_company_id"`
	// `group_company_id` by its company code and its name as they are now, both only to a caller who may
	// act in that company (the id alone otherwise); absent with it.
	GroupCompany OptGroupCompany `json:"group_company"`
}

