// Merged schema.
// Ref: #/components/schemas/ChangeRequest
type ChangeRequest struct {
	// Identifier (UUIDv7).
	ID uuid.UUID `json:"id"`
	// Optimistic-lock version; equals the ETag. Increases by one on every change.
	Version int32 `json:"version"`
	// Creation time (UTC).
	CreatedAt time.Time `json:"created_at"`
	// Principal that created the resource.
	CreatedBy uuid.UUID `json:"created_by"`
	// Time of the last change (UTC).
	UpdatedAt time.Time `json:"updated_at"`
	// Principal that made the last change. Absent on resources whose table does not record it.
	UpdatedBy OptUUID `json:"updated_by"`
	// Human change request number.
	Number string `json:"number"`
	// Title.
	Title string `json:"title"`
	// Why the change is needed.
	Rationale string `json:"rationale"`
	// Principal that proposed the change.
	AuthorID uuid.UUID `json:"author_id"`
	// Configuration version the change is based on.
	BaseVersion int32 `json:"base_version"`
	// The proposed configuration document.
	Proposed ChangeRequestProposed `json:"proposed"`
	// Risk tier, the highest of its items (1 lowest, 4 highest).
	Tier int32 `json:"tier"`
	// Lifecycle status. Open enumeration: clients must accept and preserve values not listed here; values
	// may be added within /v1.
	Status string `json:"status"`
	// Approval request (workflow context), once submitted.
	WorkflowRequestID OptUUID `json:"workflow_request_id"`
	// Configuration version created on activation.
	ActivatedVersion OptInt32 `json:"activated_version"`
	// Computed differences.
	Items []ChangeItem `json:"items"`
	// Recorded evidence.
	Evidence []Evidence `json:"evidence"`
	// What reviewers should look at in a proposal that was generated (applyCountryPack): conflicts with
	// the tenant's own settings, items kept that the source no longer has, rates that come later. Recorded
	// when the change request is created and not updated when the proposal is edited; absent when there
	// are none.
	Notes []ChangeRequestNote `json:"notes"`
}

