// Rows read from the source system per SAP table, each key the table's name in lower case (`t001` for
// T001, `agr_define` for AGR_DEFINE); internal/sap describes each table.
// Ref: #/components/schemas/MigrationExtractCounts
type MigrationExtractCounts struct {
	// Rows of SAP table T001 (company codes).
	T001 int `json:"t001"`
	// Rows of SAP table SKB1 (G/L account master per company code).
	Skb1 int `json:"skb1"`
	// Rows of SAP table LFA1 (vendor general data).
	Lfa1 int `json:"lfa1"`
	// Rows of SAP table ADRC (central addresses: the vendors' addresses, by LFA1-ADRNR).
	Adrc int `json:"adrc"`
	// Rows of SAP table LFB1 (vendor company code data).
	Lfb1 int `json:"lfb1"`
	// Rows of SAP table LFBK (vendor bank details).
	Lfbk int `json:"lfbk"`
	// Rows of SAP table EKKO (purchasing document headers).
	Ekko int `json:"ekko"`
	// Rows of SAP table EKPO (purchasing document items).
	Ekpo int `json:"ekpo"`
	// Rows of SAP table MSEG (goods movements).
	Mseg int `json:"mseg"`
	// Rows of SAP table RBKP (supplier invoice headers).
	Rbkp int `json:"rbkp"`
	// Rows of SAP table RSEG (supplier invoice items).
	Rseg int `json:"rseg"`
	// Rows of SAP table ACDOCA (Universal Journal line items).
	Acdoca int `json:"acdoca"`
	// Rows of SAP table T052 (payment terms).
	T052 int `json:"t052"`
	// Rows of SAP table T007A (tax codes).
	T007a int `json:"t007a"`
	// Rows of SAP table T030 (automatic account determination).
	T030 int `json:"t030"`
	// Rows of SAP table T169G (invoice verification tolerance limits).
	T169g int `json:"t169g"`
	// Rows of SAP table T012K (house bank accounts).
	T012k int `json:"t012k"`
	// Rows of SAP table T074 (special G/L accounts).
	T074 int `json:"t074"`
	// Rows of SAP table AGR_DEFINE (roles).
	AgrDefine int `json:"agr_define"`
	// Rows of SAP table AGR_TCODES (transactions in a role).
	AgrTcodes int `json:"agr_tcodes"`
	// Rows of SAP table AGR_USERS (role assignments).
	AgrUsers int `json:"agr_users"`
	// Rows of SAP table CSKS (cost center master data, a row per time slice; ADR-0050 §10, T56h).
	Csks int `json:"csks"`
	// Rows of SAP table CSKT (cost center texts; ADR-0050 §10, T56h).
	Cskt int `json:"cskt"`
	// Rows of SAP table CEPC (profit center master data, a row per time slice; ADR-0050 §10, T56h).
	Cepc int `json:"cepc"`
	// Rows of SAP table CEPCT (profit center texts; ADR-0050 §10, T56h).
	Cepct int `json:"cepct"`
	// Rows of SAP table CEPC_BUKRS (profit centers' company code assignments; ADR-0050 §10, T56h).
	CepcBukrs int `json:"cepc_bukrs"`
	// Rows of SAP table FAGL_SEGM (segments; ADR-0050 §10, T56h).
	FaglSegm int `json:"fagl_segm"`
	// Rows of SAP table FAGL_SEGMT (segment texts; ADR-0050 §10, T56h).
	FaglSegmt int `json:"fagl_segmt"`
	// Rows of SAP table TKA01 (controlling areas with their cost centers' standard hierarchy, KHINR;
	// ADR-0050 §10, T56h2).
	Tka01 int `json:"tka01"`
	// Rows of SAP table SETHEADER of classes 0101 and 0106 (cost and profit center groups; ADR-0050 §10,
	// T56h2).
	Setheader int `json:"setheader"`
	// Rows of SAP table SETHEADERT (the groups' texts; T56h2).
	Setheadert int `json:"setheadert"`
	// Rows of SAP table SETNODE (the groups' subgroups; ADR-0050 §10, T56h2).
	Setnode int `json:"setnode"`
	// Rows of SAP table SETLEAF (the groups' values, single centers or ranges; ADR-0050 §10, T56h2).
	Setleaf int `json:"setleaf"`
}

