// Merged schema.
// Ref: #/components/schemas/PaymentRun
type PaymentRun struct {
	// Identifier (UUIDv7).
	ID uuid.UUID `json:"id"`
	// Optimistic-lock version; equals the ETag. Increases by one on every change.
	Version int32 `json:"version"`
	// Creation time (UTC).
	CreatedAt time.Time `json:"created_at"`
	// Principal that created the resource.
	CreatedBy uuid.UUID `json:"created_by"`
	// Time of the last change (UTC).
	UpdatedAt time.Time `json:"updated_at"`
	// Principal that made the last change. Absent on resources whose table does not record it.
	UpdatedBy OptUUID `json:"updated_by"`
	// Document number.
	DocumentNumber string `json:"document_number"`
	// Legal entity.
	LegalEntityID uuid.UUID `json:"legal_entity_id"`
	// House bank paying, for a run proposed for one bank; absent when each payment names the bank that
	// pays it (T45c).
	HouseBankID OptUUID `json:"house_bank_id"`
	// The house bank's `code`, its name in the configuration; present exactly when `house_bank_id` is.
	HouseBankCode OptString `json:"house_bank_code"`
	// Run (payment) date.
	RunDate time.Time `json:"run_date"`
	// Items due on or before this date are included.
	DueBy time.Time `json:"due_by"`
	// Total of the payments.
	TotalAmount Money `json:"total_amount"`
	// Lifecycle status. Open enumeration: clients must accept and preserve values not listed here; values
	// may be added within /v1.
	Status string `json:"status"`
	// Principal that proposed the run; can never release or reject it.
	ProposedBy uuid.UUID `json:"proposed_by"`
	// Person who released or rejected the run; always differs from `proposed_by`.
	DecidedBy OptUUID `json:"decided_by"`
	// When the run was released or rejected.
	DecidedAt OptDateTime `json:"decided_at"`
	// Operation that built the proposal.
	OperationID OptUUID `json:"operation_id"`
	// The latest release operation (ADR-0012), once a release was asked for: its status says whether the
	// release is under way, done or failed; a failed one is resumed by `:release` again.
	ReleaseOperationID OptUUID `json:"release_operation_id"`
	// The latest request for a second person's approval of the release (two-person release above the
	// company's `release_dual_limit`, ADR-0038); absent when none was asked for.
	ReleaseApproval OptPaymentRunReleaseApproval `json:"release_approval"`
}

